import { useState } from 'react';

export default function App() {
  const [count, setCount] = useState(0);
  return (
    <main className="container">
      <h1>{{PROJECT_NAME}}</h1>
      <p>Edit <code>src/App.tsx</code> and save to reload.</p>
      <button onClick={() => setCount((c) => c + 1)}>
        Count is {count}
      </button>
    </main>
  );
}

